def make(n):
    result = []
    k = min(5, max(1, n // 8))
    seg_len = max(2, n // (k * 2))
    for _ in range(k):
        chars = []
        pos = 0
        while len(chars) < seg_len:
            if pos % 3 == 0:
                chars.append('_'
                           if ((pos // 3) % 2 == 0)
                           else '.')
            else:
                chars.append(chr(ord('a') + (len(chars) % 26)))
            pos += 1
        result.append([''.join(chars)])
    return result

def make(n):
    core = max(0, n - 4)
    tails = ['..', '.__.', '__..', '._._.']
    out = []
    for t in tails:
        if core >= 0:
            mid = ''.join(chr(ord('a') + (i % 26)) for i in range(core))
            out.append([t + mid + t])
    return out[:min(8, len(out))]

def make(n):
    sep_every = max(3, n // 20)
    out = []
    for start in range(sep_every):
        chars = []
        for i in range(n):
            if (i - start) % sep_every == 0 and i != start:
                chars.append('_.'[(i // sep_every) % 2])
            else:
                chars.append(chr(ord('a') + (i % 26)))
        out.append([''.join(chars)])
        if len(out) >= 8:
            break
    return out

