def make(n):
    # Build a tag like "a..b..c-d..e-f..g" with n empty parts per field
    def field(base, n):
        parts = [base]
        for i in range(n):
            parts.append('')  # empty component
            parts.append(base + str(i))
        return ".".join(parts)
    tag = f"{field('i', n)}-{field('a', n)}-{field('p', n)}"
    return [[tag]]

