def make(n):
    rnd = random.Random(n)
    parts = ["".join(rnd.choice(string.ascii_letters + string.digits) for _ in range(rnd.randint(10, 60))) for _ in range(n)]
    backs = ["\\" + c for c in string.ascii_letters[:8]]
    args = []
    if n >= 1:
        args.append([parts[0], rnd.choice(backs)])
    if n >= 2:
        args.append([parts[1], parts[0], rnd.choice(backs)])
    if n >= 3:
        args.append([parts[2], parts[1], parts[0], rnd.choice(backs)])
    if n >= 4:
        args.append([parts[3], parts[2], parts[1], parts[0], rnd.choice(backs)])
    if n >= 5:
        args.append([parts[4], parts[3], parts[2], parts[1], parts[0], rnd.choice(backs)])
    if n >= 6:
        args.append([parts[5], parts[4], parts[3], parts[2], parts[1], parts[0], rnd.choice(backs)])
    if n >= 7:
        args.append([parts[6], parts[5], parts[4], parts[3], parts[2], parts[1], parts[0], rnd.choice(backs)])
    if n >= 8:
        args.append([parts[7], parts[6], parts[5], parts[4], parts[3], parts[2], parts[1], parts[0], rnd.choice(backs)])
    return args

